import type { HeaderProps } from "./header.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Header";

// Generate child element class names for the component, should match available style slots
export const HeaderClasses = {
  root: "exp-textura_header",
  main: "exp-textura_header_main",
  breadcrumbs: "exp-textura_header_breadcrumbs",
  title: "exp-textura_header_title",
  subtitle: "exp-textura_header_subtitle",
  description: "exp-textura_header_description",
  content: "exp-textura_header_content",
  actions: "exp-textura_header_actions",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: HeaderProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<HeaderProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        //getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    flexDirection: "column",
    width: "100%",

    [`& .${HeaderClasses.main}`]: {
      display: "flex",
      flexWrap: "wrap",
      justifyContent: "space-between",
      alignItems: "flex-end",
      width: "100%",
      paddingTop: theme.toRem(theme.spacing[16]),
      ...styleSlots?.main,
    },

    [`& .${HeaderClasses.breadcrumbs}`]: {
      ...styleSlots?.breadcrumbs,
    },

    [`& .${HeaderClasses.title}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      margin: 0,
      ...theme.typography.heading.md,
      lineHeight: theme.typography.lineHeight[32],
      ...styleSlots?.title,
    },

    [`& .${HeaderClasses.subtitle}`]: {
      display: "block",
      margin: 0,
      ...theme.typography.label.md,
      lineHeight: theme.typography.lineHeight[20],
      color: theme.color.content.weak,
      paddingTop: theme.toRem(theme.spacing[8]),
      ...styleSlots?.subtitle,
    },

    [`& .${HeaderClasses.description}`]: {
      display: "block",
      margin: 0,
      ...theme.typography.body.md,
      lineHeight: theme.typography.lineHeight[20],
      color: theme.color.content.default,
      paddingTop: theme.toRem(theme.spacing[16]),
      ...styleSlots?.description,
    },

    [`& .${HeaderClasses.content}`]: {
      flexGrow: 1,
      ...styleSlots?.content,
    },

    [`& .${HeaderClasses.actions}`]: {
      display: "flex",
      alignSelf: "start",
      ...styleSlots?.actions,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledHeader = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<HeaderProps>((props) => generateStyles(props));
